van der Pol: período y amplitud del ciclo (§5.3).
opc = odeset('RelTol', 1e-10, 'AbsTol', 1e-12);
for mu = [1 5]
    f = @(t, x) [x(2); -x(1) - mu*(x(1)^2 - 1)*x(2)];
    [t, X] = ode45(f, [0 200], [0.5; 0], opc);
    k  = find(t &gt; 100);
    sube = k(X(k(1:end-1), 2) &lt; 0 & X(k(2:end), 2) &gt;= 0 & X(k(1:end-1), 1) &lt; 0);  % mínimos de x1
    T = mean(diff(t(sube)));
    fprintf('mu = %g: período %.4f, amplitud %.4f\n', mu, T, max(X(k, 1)));
end


El oscilador no uniforme (§5.4).
w = 2;  opc = odeset('RelTol', 1e-11, 'AbsTol', 1e-12);
for a = [1 1.9 1.99]
    ev = odeset(opc, 'Events', @(t, th) deal(th - 2*pi, 1, 1));
    [~, ~, te] = ode45(@(t, th) w - a*sin(th), [0 200], 0, ev);
